To execute this activity, you would need to use a programming language such as Python, C++, or Java. Here are some specific programming codes that could be used to create this image:

1. Python:
```python
import cv2

# capture image
img = cv2.imread('image.jpg')

# convert to grayscale
gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)

# apply thresholding
thresh = cv2.threshold(gray, 0, 255, cv2.THRESH_BINARY_INV+cv2.THRESH_OTSU)[1]

# find contours
contours, hierarchy = cv2.findContours(thresh, cv2.RETR_TREE, cv2.CHAIN_APPROX_SIMPLE)

# draw contours
for contour in contours:
    cv2.drawContours(img, contour, -1, (0, 255, 0), 2)

# display image
cv2.imshow('image', img)
cv2.waitKey(0)
cv2.destroyAllWindows()
```
1. C++:
```c
#include <opencv2/opencv.hpp>

int main() {
    cv::Mat image = cv::imread("image.jpg", cv::IMREAD_GRAYSCALE);
    cv::Mat thresholded;
    cv::threshold(image, thresholded, 0, 255, cv::THRESH_BINARY_INV+cv::THRESH_OTSU);
    std::vector<std::vector<cv::Point>> contours;
    std::vector<cv::Vec4i> hierarchy;
    cv::findContours(thresholded, contours, hierarchy, cv::RETR_EXTERNAL, cv::CHAIN_APPROX_SIMPLE);
    for (int i = 0; i < contours.size(); i++) {
        cv::drawContours(image, contours[i], -1, cv::Scalar(0, 255, 0), 2);

